/**
 * Adds the given byte to the internal tail buffer.
 *
 * @param b the byte to be added
 */
private void appendByte(byte b) {
    tailBuffer[currentIndex++] = b;
    if (currentIndex >= tailSize) {
        currentIndex = 0;
    }
    bytesRead++;
}
